class TreeNode {
  left: TreeNode | null;
  right: TreeNode | null;
  constructor(left: TreeNode | null, right: TreeNode | null) {
    this.left = left;
    this.right = right;
  }
}

function bottomUpTree(depth: number): TreeNode {
  if (depth > 0) {
    const d = depth - 1;
    return new TreeNode(bottomUpTree(d), bottomUpTree(d));
  }
  return new TreeNode(null, null);
}

function itemCheck(node: TreeNode): number {
  let count = 1;
  let n: TreeNode | null = node;
  // Walk right spine iteratively, recurse on left subtrees.
  while (n !== null && n.left !== null) {
    count += 1 + itemCheck(n.left);
    n = n.right;
  }
  return count;
}

function main(): void {
  const n = parseInt(process.argv[2], 10) | 0;
  const minDepth = 4;
  const maxDepth = Math.max(minDepth + 2, n);
  const stretchDepth = maxDepth + 1;

  const out: string[] = [];

  {
    const stretchTree = bottomUpTree(stretchDepth);
    out.push(
      "stretch tree of depth " + stretchDepth + "\t check: " + itemCheck(stretchTree)
    );
  }

  const longLivedTree = bottomUpTree(maxDepth);

  for (let depth = minDepth; depth <= maxDepth; depth += 2) {
    const iterations = 1 << (maxDepth - depth + minDepth);
    let check = 0;
    for (let i = 0; i < iterations; i++) {
      check += itemCheck(bottomUpTree(depth));
    }
    out.push(iterations + "\t trees of depth " + depth + "\t check: " + check);
  }

  out.push(
    "long lived tree of depth " + maxDepth + "\t check: " + itemCheck(longLivedTree)
  );

  process.stdout.write(out.join("\n") + "\n");
}

main();
```

