import { Worker } from 'worker_threads';
import * as os from 'os';

// Core enumeration/flip-counting routine, kept as plain JavaScript source so it can
// be evaluated both in the main thread and inside eval-mode worker threads
// (independent of how this TypeScript file is compiled/loaded).
const CORE = `
function run(n, idxMin, idxMax) {
  const fact = new Array(n + 1);
  fact[0] = 1;
  for (let i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;
  const p = new Int32Array(n), pp = new Int32Array(n), count = new Int32Array(n + 1);
  for (let i = 0; i < n; i++) p[i] = i;
  let idx = idxMin;
  for (let i = n - 1; i > 0; i--) {
    const d = (idx / fact[i]) | 0;
    count[i] = d;
    idx -= d * fact[i];
    for (let j = 0; j <= i; j++) pp[j] = p[j];
    for (let j = 0; j <= i; j++) p[j] = (j + d <= i) ? pp[j + d] : pp[j + d - i - 1];
  }
  let maxflips = 0, chksum = 0;
  let i = idxMin;
  for (;;) {
    if (p[0] !== 0) {
      let flips = 1;
      let first = p[0];
      if (p[first] !== 0) {
        for (let k = 0; k < n; k++) pp[k] = p[k];
        do {
          ++flips;
          for (let lo = 1, hi = first - 1; lo < hi; ++lo, --hi) {
            const t = pp[lo]; pp[lo] = pp[hi]; pp[hi] = t;
          }
          const t = pp[first]; pp[first] = first; first = t;
        } while (pp[first] !== 0);
      }
      if (flips > maxflips) maxflips = flips;
      chksum += ((i & 1) === 0) ? flips : -flips;
    }
    if (++i === idxMax) break;
    let first = p[1]; p[1] = p[0]; p[0] = first;
    let k = 1;
    while (++count[k] > k) {
      count[k++] = 0;
      const next = p[0] = p[1];
      for (let j = 1; j < k; j++) p[j] = p[j + 1];
      p[k] = first;
      first = next;
    }
  }
  return [maxflips, chksum];
}
`;

const WORKER_SRC = CORE + `
const { parentPort, workerData } = require('worker_threads');
const { n, counter, chunk, total } = workerData;
const ctr = new Int32Array(counter);
let maxf = 0, chk = 0;
for (;;) {
  const t = Atomics.add(ctr, 0, 1);
  const lo = t * chunk;
  if (lo >= total) break;
  const hi = Math.min(total, lo + chunk);
  const r = run(n, lo, hi);
  if (r[0] > maxf) maxf = r[0];
  chk += r[1];
}
parentPort.postMessage([maxf, chk]);
`;

function main(): void {
  const n = parseInt(process.argv[2], 10);
  let total = 1;
  for (let i = 2; i <= n; i++) total *= i;

  const finish = (maxf: number, chk: number): void => {
    process.stdout.write(`${chk}\nPfannkuchen(${n}) = ${maxf}\n`);
  };

  const osAny = os as any;
  let nWorkers = 1;
  try {
    nWorkers = typeof osAny.availableParallelism === 'function'
      ? osAny.availableParallelism()
      : os.cpus().length;
  } catch {
    nWorkers = 1;
  }
  if (!nWorkers || nWorkers < 1) nWorkers = 1;
  nWorkers = Math.min(nWorkers, 64);

  const runSingle = (): void => {
    const run = new Function(CORE + '\nreturn run;')() as (n: number, a: number, b: number) => number[];
    const r = run(n, 0, total);
    finish(r[0], r[1]);
  };

  if (total < 200000 || nWorkers <= 1) {
    runSingle();
    return;
  }

  const tasks = nWorkers * 8;
  let chunk = Math.ceil(total / tasks);
  chunk += chunk & 1; // keep chunks even-sized
  const counter = new SharedArrayBuffer(4);

  let remaining = nWorkers;
  let maxf = 0, chk = 0;
  let failed = false;

  for (let w = 0; w < nWorkers; w++) {
    let worker: Worker;
    try {
      worker = new Worker(WORKER_SRC, { eval: true, workerData: { n, counter, chunk, total } });
    } catch {
      if (!failed) { failed = true; runSingle(); }
      return;
    }
    worker.on('message', (r: number[]) => {
      if (r[0] > maxf) maxf = r[0];
      chk += r[1];
      if (--remaining === 0 && !failed) finish(maxf, chk);
    });
    worker.on('error', (e) => {
      if (!failed) { failed = true; runSingle(); }
    });
  }
}

main();
