import * as fs from "fs";

const IM = 139968;
const IA = 3877;
const IC = 29573;
let seed = 42;

const ALU =
  "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGG" +
  "GAGGCCGAGGCGGGCGGATCACCTGAGGTCAGGAGTTCGAGA" +
  "CCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACTAAAAAT" +
  "ACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCA" +
  "GCTACTCGGGAGGCTGAGGCAGGAGAATCGCTTGAACCCGGG" +
  "AGGCGGAGGTTGCAGTGAGCCGAGATCGCGCCACTGCACTCC" +
  "AGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";

const IUB_CHARS = "acgtBDHKMNRSVWY";
const IUB_PROBS = [0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02];

const HS_CHARS = "acgt";
const HS_PROBS = [0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008];

const LINE = 60;

function writeAll(buf: Uint8Array, len: number): void {
  let off = 0;
  while (off < len) {
    try {
      off += fs.writeSync(1, buf, off, len - off);
    } catch (e: any) {
      if (e && e.code === "EAGAIN") continue;
      throw e;
    }
  }
}

function writeString(s: string): void {
  const b = Buffer.from(s, "latin1");
  writeAll(b, b.length);
}

function makeTable(chars: string, probs: number[]): Uint8Array {
  const n = probs.length;
  const cum = new Float64Array(n);
  let acc = 0;
  for (let i = 0; i < n; i++) {
    acc += probs[i];
    cum[i] = acc;
  }
  const codes = new Uint8Array(n);
  for (let i = 0; i < n; i++) codes[i] = chars.charCodeAt(i);
  const table = new Uint8Array(IM);
  for (let s = 0; s < IM; s++) {
    const r = s / IM;
    let c = codes[n - 1];
    for (let i = 0; i < n; i++) {
      if (r < cum[i]) {
        c = codes[i];
        break;
      }
    }
    table[s] = c;
  }
  return table;
}

function repeatFasta(header: string, total: number): void {
  writeString(header + "\n");
  const aluLen = ALU.length; // 287
  const alu = new Uint8Array(aluLen);
  for (let i = 0; i < aluLen; i++) alu[i] = ALU.charCodeAt(i);

  // Periodic block: aluLen lines (gcd(287,60)=1 so period is 287 lines)
  const CYCLES = 60;
  const blockLines = aluLen * CYCLES;
  const buf = new Uint8Array(blockLines * (LINE + 1));
  let p = 0;
  let idx = 0;
  for (let l = 0; l < blockLines; l++) {
    for (let k = 0; k < LINE; k++) {
      buf[p++] = alu[idx];
      idx++;
      if (idx === aluLen) idx = 0;
    }
    buf[p++] = 10;
  }

  let lines = Math.floor(total / LINE);
  const rem = total % LINE;
  const fullLines = lines;
  while (lines >= blockLines) {
    writeAll(buf, buf.length);
    lines -= blockLines;
  }
  if (lines > 0) {
    writeAll(buf, lines * (LINE + 1));
  }
  if (rem > 0) {
    const tail = new Uint8Array(rem + 1);
    let pos = (fullLines * LINE) % aluLen;
    for (let k = 0; k < rem; k++) {
      tail[k] = alu[pos];
      pos++;
      if (pos === aluLen) pos = 0;
    }
    tail[rem] = 10;
    writeAll(tail, rem + 1);
  }
}

function randomFasta(header: string, table: Uint8Array, total: number): void {
  writeString(header + "\n");
  const LINES = 16384;
  const buf = new Uint8Array(LINES * (LINE + 1));
  let s = seed;
  let lines = Math.floor(total / LINE);
  const rem = total % LINE;
  while (lines > 0) {
    const n = lines < LINES ? lines : LINES;
    let p = 0;
    for (let l = 0; l < n; l++) {
      for (let k = 0; k < LINE; k++) {
        s = (s * IA + IC) % IM;
        buf[p++] = table[s];
      }
      buf[p++] = 10;
    }
    writeAll(buf, p);
    lines -= n;
  }
  if (rem > 0) {
    let p = 0;
    for (let k = 0; k < rem; k++) {
      s = (s * IA + IC) % IM;
      buf[p++] = table[s];
    }
    buf[p++] = 10;
    writeAll(buf, p);
  }
  seed = s;
}

function main(): void {
  const n = parseInt(process.argv[2], 10);
  const iub = makeTable(IUB_CHARS, IUB_PROBS);
  const hs = makeTable(HS_CHARS, HS_PROBS);
  repeatFasta(">ONE Homo sapiens alu", 2 * n);
  randomFasta(">TWO IUB ambiguity codes", iub, 3 * n);
  randomFasta(">THREE Homo sapiens frequency", hs, 5 * n);
}

main();
