function multiplyAv(n: number, v: Float64Array, out: Float64Array): void {
  for (let i = 0; i < n; i++) {
    let sum = 0.0;
    // A(i,j) = 1/((i+j)(i+j+1)/2 + i + 1); denominator increments by (i+j+1)
    let denom = (i * (i + 1)) / 2 + i + 1;
    let step = i + 1;
    for (let j = 0; j < n; j++) {
      sum += v[j] / denom;
      denom += step;
      step++;
    }
    out[i] = sum;
  }
}

function multiplyAtv(n: number, v: Float64Array, out: Float64Array): void {
  for (let i = 0; i < n; i++) {
    let sum = 0.0;
    // A(j,i) = 1/((i+j)(i+j+1)/2 + j + 1); denominator increments by (i+j+2)
    let denom = (i * (i + 1)) / 2 + 1;
    let step = i + 2;
    for (let j = 0; j < n; j++) {
      sum += v[j] / denom;
      denom += step;
      step++;
    }
    out[i] = sum;
  }
}

function multiplyAtAv(n: number, v: Float64Array, out: Float64Array, tmp: Float64Array): void {
  multiplyAv(n, v, tmp);
  multiplyAtv(n, tmp, out);
}

