// pidigits — unbounded spigot algorithm (Gibbons / benchmarks-game variant) using BigInt.

function main(): void {
  const N = parseInt(process.argv[2], 10);

  let numer = 1n;
  let accum = 0n;
  let denom = 1n;
  let k = 0n;

  let i = 0;
  let line = "";
  const out: string[] = [];

  while (i < N) {
    k += 1n;
    const k2 = k * 2n + 1n;

    // next_term(k)
    accum = (accum + numer * 2n) * k2;
    denom *= k2;
    numer *= k;

    if (numer > accum) continue;

    // extract digit 3 and verify against digit 4 without a second division
    const tmp = numer * 3n + accum;
    const d = tmp / denom;
    const rem = tmp - d * denom;
    if (rem + numer >= denom) continue;

    line += Number(d);
    i++;

    if (i % 10 === 0) {
      out.push(line + "\t:" + i + "\n");
      line = "";
    }

    // eliminate_digit(d)
    accum = (accum - denom * d) * 10n;
    numer *= 10n;
  }

  if (line.length > 0) {
    out.push(line.padEnd(10, " ") + "\t:" + i + "\n");
  }

  process.stdout.write(out.join(""));
}

